// \u72B6\u6001\uFF1Afile(URI) + rev \u662F"\u8EAB\u4EFD"\uFF0C\u6240\u6709\u53D1\u5F80\u5BBF\u4E3B\u7684\u6D88\u606F\u90FD\u5FC5\u987B\u5E26
